Object.assign(SNIP,{});PRESET_NOTES["l63"]={"Ví dụ: Cộng cả đoạn, hỏi tổng": "Lần cập nhật đầu chỉ chạm nút [0, 3] (t = 20, lz = 5) và các tổ tiên, không xuống tới lá. Lần hai mới đẩy ghi chú của [0, 3] xuống hai con. Tổng cả mảng 26; a[3] + a[4] = 6 + 1 = 7.", "Ví dụ: Ghi chú chỉ đi xuống khi cần": "Cộng cả mảng chỉ sửa đúng một nút (gốc: t = 24, lz = 3). Hỏi a[5] buộc phải đi xuống nhánh phải: gốc đẩy ghi chú cho hai con (lz[2] = 3 vẫn chờ, lz[3] được đẩy tiếp xuống). Nhánh trái chưa ai hỏi thì vẫn để nguyên ghi chú.", "Ví dụ: Cộng đoạn, hỏi min": "Với min, cộng v cho cả đoạn chỉ làm min tăng v (không nhân với độ dài như tổng). min(a[0..2]) = 4, min(a[1..4]) = 1.", "Ví dụ: Gán cả đoạn": "Ghi chú “gán” đè lên ghi chú cũ. Giá trị 0 cũng là một phép gán hợp lệ, nên cần cờ co[i] riêng thay vì dùng gan[i] = 0 để nghĩa là “không có”. Tổng 18, a[2] + a[3] = 7.", "Lỗi: quên đẩy ghi chú trước khi đi xuống": "In 0 rồi 1: ghi chú +5 nằm mãi ở gốc, các con không bao giờ nhận được. Tệ hơn, lần cập nhật sau tính lại t[1] = t[2] + t[3] từ hai con “còn nợ” và xóa luôn phần +5 đã có ở gốc. Mọi lần đi vào con đều phải push trước."};EX_HINTS["l63"]=[["Cây phân đoạn tổng kèm mảng lz. ap(i, l, r, v): t[i] += v · (r − l + 1), lz[i] += v.", "update: nút nằm trọn thì ap rồi dừng; ngược lại push, đi hai con, tính lại t[i]. query: push trước khi đi vào con.", "Cập nhật từng phần tử của đoạn tốn O(n) mỗi thao tác."], ["Cây min kèm lz. Cộng v cho cả đoạn của một nút: min của đoạn đó tăng đúng v, nên ap(i, v): t[i] += v, lz[i] += v (không nhân độ dài).", "Ban đầu mọi giá trị 0 nên t toàn 0 là đúng.", "Nút ngoài đoạn khi hỏi min trả về +∞."], ["Ghi chú bây giờ là “cả đoạn bằng v”: ap(i, l, r, v): t[i] = v · (r − l + 1), gan[i] = v, co[i] = true. Gán đè, không cộng dồn.", "Mức 0 cũng là một phép gán hợp lệ: dùng cờ co[i] riêng để biết nút có ghi chú hay không.", "push: nếu co[i] thì ap hai con với gan[i], rồi co[i] = false."]];
/* ===================== BÀI 63 · Cập nhật lười (lazy propagation) ===================== */
/* Bài 63 · Cập nhật lười (lazy propagation)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR63=[{label:"Ví dụ: Cộng cả đoạn, hỏi tổng",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> t, lz;\n\nvoid ap(int i, int l, int r, long long v) {   // cộng v cho cả đoạn của nút i\n    t[i] += v * (r - l + 1);\n    lz[i] += v;\n}\n\nvoid push(int i, int l, int r) {              // chuyển ghi chú xuống hai con\n    if (lz[i] == 0) return;\n    int m = (l + r) / 2;\n    ap(2 * i, l, m, lz[i]);\n    ap(2 * i + 1, m + 1, r, lz[i]);\n    lz[i] = 0;\n}\n\nvoid update(int i, int l, int r, int x, int y, long long v) {\n    if (y < l || r < x) return;\n    if (x <= l && r <= y) { ap(i, l, r, v); return; }   // nằm trọn: ghi chú rồi dừng\n    push(i, l, r);\n    int m = (l + r) / 2;\n    update(2 * i, l, m, x, y, v);\n    update(2 * i + 1, m + 1, r, x, y, v);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return 0;\n    if (x <= l && r <= y) return t[i];\n    push(i, l, r);\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nint main() {\n    n = 8;\n    t.assign(4 * n, 0);\n    lz.assign(4 * n, 0);               // mảng ban đầu toàn 0\n    update(1, 0, n - 1, 0, 3, 5);      // a[0..3] += 5\n    update(1, 0, n - 1, 2, 7, 1);      // a[2..7] += 1\n    cout << query(1, 0, n - 1, 0, 7) << \" \" << query(1, 0, n - 1, 3, 4) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"cells",of:"lz",ptr:["i"]},{type:"calls"}],py:{code:"def ap(i, l, r, v):                    # cộng v cho cả đoạn của nút i\n    t[i] += v * (r - l + 1)\n    lz[i] += v\n\ndef push(i, l, r):                     # chuyển ghi chú xuống hai con\n    if lz[i] == 0:\n        return\n    m = (l + r) // 2\n    ap(2 * i, l, m, lz[i])\n    ap(2 * i + 1, m + 1, r, lz[i])\n    lz[i] = 0\n\ndef update(i, l, r, x, y, v):\n    if y < l or r < x:\n        return\n    if x <= l and r <= y:              # nằm trọn: ghi chú rồi dừng\n        ap(i, l, r, v)\n        return\n    push(i, l, r)\n    m = (l + r) // 2\n    update(2 * i, l, m, x, y, v)\n    update(2 * i + 1, m + 1, r, x, y, v)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return 0\n    if x <= l and r <= y:\n        return t[i]\n    push(i, l, r)\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\nn = 8\nt = [0] * (4 * n)\nlz = [0] * (4 * n)                     # mảng ban đầu toàn 0\nupdate(1, 0, n - 1, 0, 3, 5)           # a[0..3] += 5\nupdate(1, 0, n - 1, 2, 7, 1)           # a[2..7] += 1\nprint(query(1, 0, n - 1, 0, 7), query(1, 0, n - 1, 3, 4))"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] t, lz;\n\n    static void Ap(int i, int l, int r, long v)   // cộng v cho cả đoạn của nút i\n    {\n        t[i] += v * (r - l + 1);\n        lz[i] += v;\n    }\n\n    static void Push(int i, int l, int r)         // chuyển ghi chú xuống hai con\n    {\n        if (lz[i] == 0) return;\n        int m = (l + r) / 2;\n        Ap(2 * i, l, m, lz[i]);\n        Ap(2 * i + 1, m + 1, r, lz[i]);\n        lz[i] = 0;\n    }\n\n    static void Update(int i, int l, int r, int x, int y, long v)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y) { Ap(i, l, r, v); return; }   // nằm trọn: ghi chú rồi dừng\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        Update(2 * i, l, m, x, y, v);\n        Update(2 * i + 1, m + 1, r, x, y, v);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return 0;\n        if (x <= l && r <= y) return t[i];\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Main()\n    {\n        n = 8;\n        t = new long[4 * n];\n        lz = new long[4 * n];                  // mảng ban đầu toàn 0\n        Update(1, 0, n - 1, 0, 3, 5);          // a[0..3] += 5\n        Update(1, 0, n - 1, 2, 7, 1);          // a[2..7] += 1\n        Console.WriteLine(Query(1, 0, n - 1, 0, 7) + \" \" + Query(1, 0, n - 1, 3, 4));\n    }\n}"}},{label:"Ví dụ: Ghi chú chỉ đi xuống khi cần",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> t, lz;\n\nvoid ap(int i, int l, int r, long long v) {   // cộng v cho cả đoạn của nút i\n    t[i] += v * (r - l + 1);\n    lz[i] += v;\n}\n\nvoid push(int i, int l, int r) {              // chuyển ghi chú xuống hai con\n    if (lz[i] == 0) return;\n    int m = (l + r) / 2;\n    ap(2 * i, l, m, lz[i]);\n    ap(2 * i + 1, m + 1, r, lz[i]);\n    lz[i] = 0;\n}\n\nvoid update(int i, int l, int r, int x, int y, long long v) {\n    if (y < l || r < x) return;\n    if (x <= l && r <= y) { ap(i, l, r, v); return; }   // nằm trọn: ghi chú rồi dừng\n    push(i, l, r);\n    int m = (l + r) / 2;\n    update(2 * i, l, m, x, y, v);\n    update(2 * i + 1, m + 1, r, x, y, v);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return 0;\n    if (x <= l && r <= y) return t[i];\n    push(i, l, r);\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nint main() {\n    n = 8;\n    t.assign(4 * n, 0);\n    lz.assign(4 * n, 0);\n    update(1, 0, n - 1, 0, 7, 3);      // cả mảng += 3: chỉ chạm gốc\n    cout << t[1] << \" \" << lz[1] << \" \" << lz[2] << \"\\n\";\n    cout << query(1, 0, n - 1, 5, 5) << \"\\n\";   // phải đi xuống: ghi chú được đẩy dọc đường\n    cout << lz[1] << \" \" << lz[2] << \" \" << lz[3] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"lz",ptr:["i"]},{type:"calls"}],py:{code:"def ap(i, l, r, v):                    # cộng v cho cả đoạn của nút i\n    t[i] += v * (r - l + 1)\n    lz[i] += v\n\ndef push(i, l, r):                     # chuyển ghi chú xuống hai con\n    if lz[i] == 0:\n        return\n    m = (l + r) // 2\n    ap(2 * i, l, m, lz[i])\n    ap(2 * i + 1, m + 1, r, lz[i])\n    lz[i] = 0\n\ndef update(i, l, r, x, y, v):\n    if y < l or r < x:\n        return\n    if x <= l and r <= y:              # nằm trọn: ghi chú rồi dừng\n        ap(i, l, r, v)\n        return\n    push(i, l, r)\n    m = (l + r) // 2\n    update(2 * i, l, m, x, y, v)\n    update(2 * i + 1, m + 1, r, x, y, v)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return 0\n    if x <= l and r <= y:\n        return t[i]\n    push(i, l, r)\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\nn = 8\nt = [0] * (4 * n)\nlz = [0] * (4 * n)\nupdate(1, 0, n - 1, 0, 7, 3)           # cả mảng += 3: chỉ chạm gốc\nprint(t[1], lz[1], lz[2])\nprint(query(1, 0, n - 1, 5, 5))        # phải đi xuống: ghi chú được đẩy dọc đường\nprint(lz[1], lz[2], lz[3])"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] t, lz;\n\n    static void Ap(int i, int l, int r, long v)   // cộng v cho cả đoạn của nút i\n    {\n        t[i] += v * (r - l + 1);\n        lz[i] += v;\n    }\n\n    static void Push(int i, int l, int r)         // chuyển ghi chú xuống hai con\n    {\n        if (lz[i] == 0) return;\n        int m = (l + r) / 2;\n        Ap(2 * i, l, m, lz[i]);\n        Ap(2 * i + 1, m + 1, r, lz[i]);\n        lz[i] = 0;\n    }\n\n    static void Update(int i, int l, int r, int x, int y, long v)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y) { Ap(i, l, r, v); return; }   // nằm trọn: ghi chú rồi dừng\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        Update(2 * i, l, m, x, y, v);\n        Update(2 * i + 1, m + 1, r, x, y, v);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return 0;\n        if (x <= l && r <= y) return t[i];\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Main()\n    {\n        n = 8;\n        t = new long[4 * n];\n        lz = new long[4 * n];\n        Update(1, 0, n - 1, 0, 7, 3);          // cả mảng += 3: chỉ chạm gốc\n        Console.WriteLine(t[1] + \" \" + lz[1] + \" \" + lz[2]);\n        Console.WriteLine(Query(1, 0, n - 1, 5, 5));   // phải đi xuống: ghi chú được đẩy dọc đường\n        Console.WriteLine(lz[1] + \" \" + lz[2] + \" \" + lz[3]);\n    }\n}"}},{label:"Ví dụ: Cộng đoạn, hỏi min",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> t, lz;\n\nvoid ap(int i, long long v) { t[i] += v; lz[i] += v; }   // min của cả đoạn tăng đúng v\n\nvoid push(int i) {\n    if (lz[i] == 0) return;\n    ap(2 * i, lz[i]);\n    ap(2 * i + 1, lz[i]);\n    lz[i] = 0;\n}\n\nvoid update(int i, int l, int r, int x, int y, long long v) {\n    if (y < l || r < x) return;\n    if (x <= l && r <= y) { ap(i, v); return; }\n    push(i);\n    int m = (l + r) / 2;\n    update(2 * i, l, m, x, y, v);\n    update(2 * i + 1, m + 1, r, x, y, v);\n    t[i] = min(t[2 * i], t[2 * i + 1]);\n}\n\nlong long query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return 4e18;\n    if (x <= l && r <= y) return t[i];\n    push(i);\n    int m = (l + r) / 2;\n    return min(query(2 * i, l, m, x, y), query(2 * i + 1, m + 1, r, x, y));\n}\n\nint main() {\n    n = 6;\n    t.assign(4 * n, 0);\n    lz.assign(4 * n, 0);\n    update(1, 0, n - 1, 0, 2, 4);      // a = 4 4 4 0 0 0\n    update(1, 0, n - 1, 2, 5, 1);      // a = 4 4 5 1 1 1\n    cout << query(1, 0, n - 1, 0, 2) << \" \" << query(1, 0, n - 1, 1, 4) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"cells",of:"lz",ptr:["i"]}],py:{code:"def ap(i, v):                          # min của cả đoạn tăng đúng v\n    t[i] += v\n    lz[i] += v\n\ndef push(i):\n    if lz[i] == 0:\n        return\n    ap(2 * i, lz[i])\n    ap(2 * i + 1, lz[i])\n    lz[i] = 0\n\ndef update(i, l, r, x, y, v):\n    if y < l or r < x:\n        return\n    if x <= l and r <= y:\n        ap(i, v)\n        return\n    push(i)\n    m = (l + r) // 2\n    update(2 * i, l, m, x, y, v)\n    update(2 * i + 1, m + 1, r, x, y, v)\n    t[i] = min(t[2 * i], t[2 * i + 1])\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return INF\n    if x <= l and r <= y:\n        return t[i]\n    push(i)\n    m = (l + r) // 2\n    return min(query(2 * i, l, m, x, y), query(2 * i + 1, m + 1, r, x, y))\n\nINF = float(\"inf\")\nn = 6\nt = [0] * (4 * n)\nlz = [0] * (4 * n)\nupdate(1, 0, n - 1, 0, 2, 4)           # a = 4 4 4 0 0 0\nupdate(1, 0, n - 1, 2, 5, 1)           # a = 4 4 5 1 1 1\nprint(query(1, 0, n - 1, 0, 2), query(1, 0, n - 1, 1, 4))"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] t, lz;\n    const long INF = long.MaxValue;\n\n    static void Ap(int i, long v)                 // min của cả đoạn tăng đúng v\n    {\n        t[i] += v;\n        lz[i] += v;\n    }\n\n    static void Push(int i)\n    {\n        if (lz[i] == 0) return;\n        Ap(2 * i, lz[i]);\n        Ap(2 * i + 1, lz[i]);\n        lz[i] = 0;\n    }\n\n    static void Update(int i, int l, int r, int x, int y, long v)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y) { Ap(i, v); return; }\n        Push(i);\n        int m = (l + r) / 2;\n        Update(2 * i, l, m, x, y, v);\n        Update(2 * i + 1, m + 1, r, x, y, v);\n        t[i] = Math.Min(t[2 * i], t[2 * i + 1]);\n    }\n\n    static long Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return INF;\n        if (x <= l && r <= y) return t[i];\n        Push(i);\n        int m = (l + r) / 2;\n        return Math.Min(Query(2 * i, l, m, x, y), Query(2 * i + 1, m + 1, r, x, y));\n    }\n\n    static void Main()\n    {\n        n = 6;\n        t = new long[4 * n];\n        lz = new long[4 * n];\n        Update(1, 0, n - 1, 0, 2, 4);          // a = 4 4 4 0 0 0\n        Update(1, 0, n - 1, 2, 5, 1);          // a = 4 4 5 1 1 1\n        Console.WriteLine(Query(1, 0, n - 1, 0, 2) + \" \" + Query(1, 0, n - 1, 1, 4));\n    }\n}"}},{label:"Ví dụ: Gán cả đoạn",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> t, gan;\nvector<bool> co;                       // co[i]: nút i đang có ghi chú “cả đoạn bằng gan[i]”\n\nvoid ap(int i, int l, int r, long long v) { t[i] = v * (r - l + 1); gan[i] = v; co[i] = true; }\n\nvoid push(int i, int l, int r) {\n    if (!co[i]) return;\n    int m = (l + r) / 2;\n    ap(2 * i, l, m, gan[i]);           // gán đè, không cộng dồn\n    ap(2 * i + 1, m + 1, r, gan[i]);\n    co[i] = false;\n}\n\nvoid update(int i, int l, int r, int x, int y, long long v) {\n    if (y < l || r < x) return;\n    if (x <= l && r <= y) { ap(i, l, r, v); return; }\n    push(i, l, r);\n    int m = (l + r) / 2;\n    update(2 * i, l, m, x, y, v);\n    update(2 * i + 1, m + 1, r, x, y, v);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return 0;\n    if (x <= l && r <= y) return t[i];\n    push(i, l, r);\n    int m = (l + r) / 2;\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nint main() {\n    n = 6;\n    t.assign(4 * n, 0); gan.assign(4 * n, 0); co.assign(4 * n, false);\n    update(1, 0, n - 1, 0, 5, 2);      // a = 2 2 2 2 2 2\n    update(1, 0, n - 1, 1, 3, 7);      // a = 2 7 7 7 2 2\n    update(1, 0, n - 1, 3, 4, 0);      // a = 2 7 7 0 0 2\n    cout << query(1, 0, n - 1, 0, 5) << \" \" << query(1, 0, n - 1, 2, 3) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"cells",of:"gan",ptr:["i"]}],py:{code:"def ap(i, l, r, v):                    # cả đoạn của nút i bằng v\n    t[i] = v * (r - l + 1)\n    gan[i] = v\n    co[i] = True\n\ndef push(i, l, r):\n    if not co[i]:\n        return\n    m = (l + r) // 2\n    ap(2 * i, l, m, gan[i])            # gán đè, không cộng dồn\n    ap(2 * i + 1, m + 1, r, gan[i])\n    co[i] = False\n\ndef update(i, l, r, x, y, v):\n    if y < l or r < x:\n        return\n    if x <= l and r <= y:\n        ap(i, l, r, v)\n        return\n    push(i, l, r)\n    m = (l + r) // 2\n    update(2 * i, l, m, x, y, v)\n    update(2 * i + 1, m + 1, r, x, y, v)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return 0\n    if x <= l and r <= y:\n        return t[i]\n    push(i, l, r)\n    m = (l + r) // 2\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\nn = 6\nt = [0] * (4 * n)\ngan = [0] * (4 * n)\nco = [False] * (4 * n)                 # co[i]: nút i đang có ghi chú “cả đoạn bằng gan[i]”\nupdate(1, 0, n - 1, 0, 5, 2)           # a = 2 2 2 2 2 2\nupdate(1, 0, n - 1, 1, 3, 7)           # a = 2 7 7 7 2 2\nupdate(1, 0, n - 1, 3, 4, 0)           # a = 2 7 7 0 0 2\nprint(query(1, 0, n - 1, 0, 5), query(1, 0, n - 1, 2, 3))"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] t, gan;\n    static bool[] co;                             // co[i]: nút i đang có ghi chú “cả đoạn bằng gan[i]”\n\n    static void Ap(int i, int l, int r, long v)\n    {\n        t[i] = v * (r - l + 1);\n        gan[i] = v;\n        co[i] = true;\n    }\n\n    static void Push(int i, int l, int r)\n    {\n        if (!co[i]) return;\n        int m = (l + r) / 2;\n        Ap(2 * i, l, m, gan[i]);                  // gán đè, không cộng dồn\n        Ap(2 * i + 1, m + 1, r, gan[i]);\n        co[i] = false;\n    }\n\n    static void Update(int i, int l, int r, int x, int y, long v)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y) { Ap(i, l, r, v); return; }   // nằm trọn: ghi chú rồi dừng\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        Update(2 * i, l, m, x, y, v);\n        Update(2 * i + 1, m + 1, r, x, y, v);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return 0;\n        if (x <= l && r <= y) return t[i];\n        Push(i, l, r);\n        int m = (l + r) / 2;\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Main()\n    {\n        n = 6;\n        t = new long[4 * n];\n        gan = new long[4 * n];\n        co = new bool[4 * n];\n        Update(1, 0, n - 1, 0, 5, 2);          // a = 2 2 2 2 2 2\n        Update(1, 0, n - 1, 1, 3, 7);          // a = 2 7 7 7 2 2\n        Update(1, 0, n - 1, 3, 4, 0);          // a = 2 7 7 0 0 2\n        Console.WriteLine(Query(1, 0, n - 1, 0, 5) + \" \" + Query(1, 0, n - 1, 2, 3));\n    }\n}"}},{label:"Lỗi: quên đẩy ghi chú trước khi đi xuống",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> t, lz;\n\nvoid ap(int i, int l, int r, long long v) { t[i] += v * (r - l + 1); lz[i] += v; }\n\nvoid update(int i, int l, int r, int x, int y, long long v) {\n    if (y < l || r < x) return;\n    if (x <= l && r <= y) { ap(i, l, r, v); return; }\n    int m = (l + r) / 2;               // SAI: thiếu push(i, l, r)\n    update(2 * i, l, m, x, y, v);\n    update(2 * i + 1, m + 1, r, x, y, v);\n    t[i] = t[2 * i] + t[2 * i + 1];\n}\n\nlong long query(int i, int l, int r, int x, int y) {\n    if (y < l || r < x) return 0;\n    if (x <= l && r <= y) return t[i];\n    int m = (l + r) / 2;               // SAI: thiếu push(i, l, r)\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y);\n}\n\nint main() {\n    n = 4;\n    t.assign(4 * n, 0);\n    lz.assign(4 * n, 0);\n    update(1, 0, n - 1, 0, 3, 5);      // cả mảng += 5: ghi chú ở gốc\n    cout << query(1, 0, n - 1, 1, 2) << \"\\n\";   // đúng phải là 10\n    update(1, 0, n - 1, 0, 0, 1);      // tính lại t[1] từ hai con chưa nhận ghi chú\n    cout << query(1, 0, n - 1, 0, 3) << \"\\n\";   // đúng phải là 21\n    return 0;\n}",viz:[{type:"cells",of:"t",ptr:["i"]},{type:"cells",of:"lz",ptr:["i"]}],py:{code:"def ap(i, l, r, v):\n    t[i] += v * (r - l + 1)\n    lz[i] += v\n\ndef update(i, l, r, x, y, v):\n    if y < l or r < x:\n        return\n    if x <= l and r <= y:\n        ap(i, l, r, v)\n        return\n    m = (l + r) // 2                   # SAI: thiếu push(i, l, r)\n    update(2 * i, l, m, x, y, v)\n    update(2 * i + 1, m + 1, r, x, y, v)\n    t[i] = t[2 * i] + t[2 * i + 1]\n\ndef query(i, l, r, x, y):\n    if y < l or r < x:\n        return 0\n    if x <= l and r <= y:\n        return t[i]\n    m = (l + r) // 2                   # SAI: thiếu push(i, l, r)\n    return query(2 * i, l, m, x, y) + query(2 * i + 1, m + 1, r, x, y)\n\nn = 4\nt = [0] * (4 * n)\nlz = [0] * (4 * n)\nupdate(1, 0, n - 1, 0, 3, 5)           # cả mảng += 5: ghi chú ở gốc\nprint(query(1, 0, n - 1, 1, 2))        # đúng phải là 10\nupdate(1, 0, n - 1, 0, 0, 1)           # tính lại t[1] từ hai con chưa nhận ghi chú\nprint(query(1, 0, n - 1, 0, 3))        # đúng phải là 21"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] t, lz;\n\n    static void Ap(int i, int l, int r, long v) { t[i] += v * (r - l + 1); lz[i] += v; }\n\n    static void Update(int i, int l, int r, int x, int y, long v)\n    {\n        if (y < l || r < x) return;\n        if (x <= l && r <= y) { Ap(i, l, r, v); return; }\n        int m = (l + r) / 2;               // SAI: thiếu Push(i, l, r)\n        Update(2 * i, l, m, x, y, v);\n        Update(2 * i + 1, m + 1, r, x, y, v);\n        t[i] = t[2 * i] + t[2 * i + 1];\n    }\n\n    static long Query(int i, int l, int r, int x, int y)\n    {\n        if (y < l || r < x) return 0;\n        if (x <= l && r <= y) return t[i];\n        int m = (l + r) / 2;               // SAI: thiếu Push(i, l, r)\n        return Query(2 * i, l, m, x, y) + Query(2 * i + 1, m + 1, r, x, y);\n    }\n\n    static void Main()\n    {\n        n = 4;\n        t = new long[4 * n];\n        lz = new long[4 * n];\n        Update(1, 0, n - 1, 0, 3, 5);          // cả mảng += 5: ghi chú ở gốc\n        Console.WriteLine(Query(1, 0, n - 1, 1, 2));   // đúng phải là 10\n        Update(1, 0, n - 1, 0, 0, 1);          // tính lại t[1] từ hai con chưa nhận ghi chú\n        Console.WriteLine(Query(1, 0, n - 1, 0, 3));   // đúng phải là 21\n    }\n}"}}];
